'use strict';
const {manufacturers}=window.HM_DATA;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let showAllMakers=true;
function renderMakers(){const q=$('#makerSearch').value.toLowerCase().trim();const list=manufacturers.filter(m=>`${m.company} ${m.country} ${m.flagship_model}`.toLowerCase().includes(q));$('#makerCount').textContent=`${list.length} manufacturers`;$('#makerRows').innerHTML=list.slice(0,showAllMakers||q?manufacturers.length:10).map(m=>`<tr><td>${String(m.id).padStart(2,'0')}</td><td>${esc(m.company)}</td><td>${esc(m.country)}</td><td>${esc(m.flagship_model)}<small>${esc(m.form_factor)}</small></td><td>${esc(m.availability)}</td><td><a href="${esc(m.official_url)}" target="_blank" rel="noopener" aria-label="Official source for ${esc(m.company)}">Official ↗</a></td></tr>`).join('')||'<tr><td colspan="6">No matching manufacturers.</td></tr>';$('#allMakers').hidden=!!q||showAllMakers;}
$('#downloadDirectory').onclick=()=>{const rows=[['Index','Manufacturer','Base','Model','Status','Official source','Checked'],...manufacturers.map(m=>[m.id,m.company,m.country,m.flagship_model,m.availability,m.official_url,m.checked_date])];const csv=rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));a.href=url;a.download='humanoid-100-manufacturers.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#makerSearch').oninput=renderMakers;$('#allMakers').onclick=()=>{showAllMakers=true;renderMakers()};renderMakers();
